const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.0",
  "engineVersion": "ab56fe763f921d033a6c195e7ddeb3e255bdbb57",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../lib/generated/prisma\"\n  binaryTargets = [\"native\", \"rhel-openssl-3.0.x\", \"linux-arm64-openssl-3.0.x\", \"linux-musl-arm64-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==========================================\n// CORE USER MODEL\n// ==========================================\n\nmodel User {\n  id          String    @id @default(cuid())\n  name        String?\n  email       String    @unique\n  phone       String?\n  clerkUserId String?   @unique\n  avatar      String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  isAdmin     Boolean   @default(false)\n  nationalId  String?\n  address     String?\n  dateOfBirth DateTime? // Date of birth for KYC\n\n  // Relations\n  memberships         Membership[]\n  ownedGroups         Group[]                @relation(\"GroupOwner\")\n  transactions        Transaction[]\n  personalSavings     PersonalSavings?\n  savingsGoals        SavingsGoal[]\n  notifications       Notification[]\n  sentInvitations     GroupInvitation[]      @relation(\"SentInvitations\")\n  receivedInvitations GroupInvitation[]      @relation(\"ReceivedInvitations\")\n  wallet              Wallet?\n  contributions       Contribution[]\n  loanRequests        LoanRequest[]          @relation(\"UserLoanRequests\")\n  loanVotes           LoanVote[]             @relation(\"UserLoanVotes\")\n  personalDocuments   PersonalLoanDocuments?\n  solarDocuments      SolarLoanDocuments?\n  individualLoans     IndividualLoan[]\n  insurancePolicies   InsurancePolicy[]      @relation(\"UserInsurancePolicies\")\n\n  // Pollen Ledger Relations\n  memberBalance         MemberBalance?\n  ledgerEntries         LedgerEntry[]\n  interestDistributions InterestDistribution[]\n}\n\n// ==========================================\n// BLOG MODELS\n// ==========================================\n\nmodel BlogPost {\n  id              String         @id @default(cuid())\n  title           String\n  Description     String\n  author          String\n  author_Position String\n  category        String?\n  status          String?        @default(\"draft\")\n  Blog_image      String\n  blog_tags       String[]\n  read_time       String\n  likes           Int            @default(0)\n  views           Int            @default(0)\n  engagement      Float          @default(0)\n  posted_at       DateTime       @default(now())\n  updated_at_Date DateTime       @default(now())\n  blog_comments   BlogComment[]\n  blog_bookmarks  BlogBookmark[]\n  blog_likes      BlogLike[]\n}\n\nmodel BlogCategory {\n  id          String @id @default(cuid())\n  name        String\n  description String\n}\n\nmodel BlogComment {\n  id            String   @id @default(cuid())\n  comment       String   @db.Text\n  comment_by    String\n  comment_at    DateTime @default(now())\n  comment_likes Int      @default(0)\n  blog_post_id  String\n  parent_id     String?\n  audio_url     String?\n\n  // Sentiment Analysis Fields\n  sentiment           String?\n  sentimentScore      Float?\n  sentimentConfidence Float?\n  emotions            String[]  @default([])\n  analyzedAt          DateTime?\n\n  // Content Moderation Fields\n  moderationStatus String?   @default(\"pending\")\n  moderationScore  Float?\n  moderationFlags  String[]  @default([])\n  moderatedAt      DateTime?\n  moderatedBy      String?\n\n  blog_post BlogPost      @relation(fields: [blog_post_id], references: [id], onDelete: Cascade)\n  parent    BlogComment?  @relation(\"CommentReplies\", fields: [parent_id], references: [id], onDelete: Cascade)\n  replies   BlogComment[] @relation(\"CommentReplies\")\n\n  @@index([blog_post_id])\n  @@index([parent_id])\n  @@index([comment_by])\n  @@index([comment_at])\n  @@index([moderationStatus])\n}\n\nmodel BlogBookmark {\n  id           String   @id @default(cuid())\n  user_id      String\n  blog_post_id String\n  blog_post    BlogPost @relation(fields: [blog_post_id], references: [id], onDelete: Cascade)\n  created_at   DateTime @default(now())\n\n  @@unique([user_id, blog_post_id])\n  @@index([user_id])\n  @@index([blog_post_id])\n}\n\nmodel BlogLike {\n  id           String   @id @default(cuid())\n  user_id      String\n  blog_post_id String\n  blog_post    BlogPost @relation(fields: [blog_post_id], references: [id], onDelete: Cascade)\n  created_at   DateTime @default(now())\n\n  @@unique([user_id, blog_post_id])\n  @@index([user_id])\n  @@index([blog_post_id])\n}\n\nmodel UserFollow {\n  id          String   @id @default(cuid())\n  follower_id String\n  author_name String\n  created_at  DateTime @default(now())\n\n  @@unique([follower_id, author_name])\n  @@index([follower_id])\n  @@index([author_name])\n}\n\n// ==========================================\n// SERVICE MODEL\n// ==========================================\n\nmodel Service {\n  id           String   @id @default(cuid())\n  name         String\n  nameKey      String?\n  description  String\n  category     String\n  status       String   @default(\"active\")\n  icon         String?\n  image        String?\n  users        Int?     @default(0)\n  revenue      Int?     @default(0)\n  growth       Float?   @default(0)\n  keyFeatures  String[]\n  requirements String[]\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  @@index([category])\n  @@index([status])\n}\n\n// ==========================================\n// GROUP & MEMBERSHIP MODELS\n// ==========================================\n\nmodel Group {\n  id                    String                @id @default(cuid())\n  name                  String\n  description           String?\n  logo                  String?\n  groupCode             String?\n  createdAt             DateTime              @default(now())\n  updatedAt             DateTime              @updatedAt\n  ownerId               String\n  owner                 User                  @relation(\"GroupOwner\", fields: [ownerId], references: [id])\n  privacy               GroupPrivacy          @default(PRIVATE)\n  governanceType        GovernanceType        @default(ADMIN)\n  contributionAmount    Decimal               @default(0)\n  contributionFrequency ContributionFrequency @default(MONTHLY)\n  depositGoal           Decimal?\n  latePenaltyFee        Decimal               @default(0)\n  gracePeriod           Int                   @default(3)\n  interestRate          Decimal               @default(0)\n  allowEarlyWithdrawal  Boolean               @default(false)\n  earlyWithdrawalFee    Decimal               @default(0)\n  requireApproval       Boolean               @default(true)\n  autoReminders         Boolean               @default(true)\n  votingThreshold       Int                   @default(50)\n  allowLateJoining      Boolean               @default(true)\n  groupDuration         Int?\n  maxMembers            Int?\n  meetingFrequency      MeetingFrequency      @default(WEEKLY)\n  groupRules            String?               @db.Text\n  bylaws                String?               @db.Text\n  tags                  String?\n  status                GroupStatus           @default(ACTIVE)\n\n  // Relations\n  memberships       Membership[]\n  transactions      Transaction[]\n  meetings          Meeting[]\n  invitations       GroupInvitation[]\n  contributions     Contribution[]\n  loanRequests      LoanRequest[]     @relation(\"GroupLoanRequests\")\n  insurancePolicies InsurancePolicy[] @relation(\"GroupInsurancePolicies\")\n\n  // Pollen Ledger Relations\n  villageLedger VillageLedger?\n  aavePosition  AavePosition?\n  groupBudget   GroupBudget?\n}\n\nmodel GroupBudget {\n  id            String   @id @default(cuid())\n  groupId       String   @unique\n  group         Group    @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  monthlyAmount Float\n  spentAmount   Float    @default(0)\n  categories    Json     @default(\"[]\")\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([groupId])\n}\n\nmodel Membership {\n  id               String           @id @default(cuid())\n  userId           String\n  user             User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  groupId          String\n  group            Group            @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  role             MembershipRole   @default(MEMBER)\n  joinedAt         DateTime         @default(now())\n  status           MembershipStatus @default(ACTIVE)\n  balance          Decimal          @default(0)\n  totalContributed Decimal          @default(0)\n  lastContribution DateTime?\n\n  // Relations\n  votes                    Vote[]\n  meetingAttendees         MeetingAttendee[]\n  voteResults              VoteResult[]\n  loanVotes                LoanVote[]                @relation(\"MembershipLoanVotes\")\n  chairedMeetings          Meeting[]                 @relation(\"MeetingChairperson\")\n  noteTakerMeetings        Meeting[]                 @relation(\"MeetingNoteTaker\")\n  meetingGoalContributions MeetingGoalContribution[]\n\n  @@unique([userId, groupId])\n}\n\n// ==========================================\n// TRANSACTION MODEL\n// ==========================================\n\nmodel Transaction {\n  id            String            @id @default(cuid())\n  amount        Decimal\n  type          TransactionType\n  status        TransactionStatus @default(PENDING)\n  description   String?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n  userId        String\n  user          User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  groupId       String?\n  group         Group?            @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  momoNumber    String?\n  reference     String?           @unique\n  feeAmount     Decimal?\n  walletId      String?\n  wallet        Wallet?           @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  contribution  Contribution?\n  loanRequestId String?\n  loanRequest   LoanRequest?      @relation(fields: [loanRequestId], references: [id], onDelete: Cascade)\n}\n\n// ==========================================\n// SAVINGS MODELS\n// ==========================================\n\nmodel PersonalSavings {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  balance   Decimal  @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel SavingsGoal {\n  id            String               @id @default(cuid())\n  name          String\n  targetAmount  Decimal\n  currentAmount Decimal              @default(0)\n  deadline      DateTime?\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n  userId        String\n  user          User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isCompleted   Boolean              @default(false)\n  transactions  SavingsTransaction[]\n  aiAnalyses    AIGoalAnalysis[]\n}\n\nmodel SavingsTransaction {\n  id            String   @id @default(cuid())\n  savingsGoalId String\n  amount        Float\n  type          String\n  description   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  savingsGoal SavingsGoal @relation(fields: [savingsGoalId], references: [id], onDelete: Cascade)\n\n  @@index([savingsGoalId])\n}\n\nmodel AIGoalAnalysis {\n  id                          String   @id @default(cuid())\n  savingsGoalId               String\n  creditScore                 Int\n  scoreCategory               String\n  riskLevel                   String\n  analysis                    String   @db.Text\n  recommendations             String[]\n  predictedCompletionDate     DateTime\n  onTrack                     Boolean\n  confidence                  Int\n  progressPercentage          Decimal\n  avgMonthlyContribution      Decimal\n  requiredMonthlyContribution Decimal\n  daysUntilDeadline           Int\n  remainingAmount             Decimal\n  createdAt                   DateTime @default(now())\n\n  savingsGoal SavingsGoal @relation(fields: [savingsGoalId], references: [id], onDelete: Cascade)\n\n  @@index([savingsGoalId])\n  @@index([createdAt])\n}\n\n// ==========================================\n// MEETING & VOTING MODELS\n// ==========================================\n\nmodel Meeting {\n  id                          String                 @id @default(cuid())\n  title                       String\n  description                 String?\n  agenda                      String[]               @default([])\n  date                        DateTime\n  location                    String?\n  isVirtual                   Boolean                @default(false)\n  meetingLink                 String?\n  minutesText                 String?\n  minutesFileUrl              String?\n  minutesKeyDecisions         String[]               @default([])\n  minutesActionItems          String[]               @default([])\n  minutesActionItemsCompleted Boolean[]              @default([])\n  createdAt                   DateTime               @default(now())\n  updatedAt                   DateTime               @updatedAt\n  groupId                     String\n  group                       Group                  @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  attendees                   MeetingAttendee[]\n  chairpersonMembershipId     String?\n  chairperson                 Membership?            @relation(\"MeetingChairperson\", fields: [chairpersonMembershipId], references: [id])\n  noteTakerMembershipId       String?\n  noteTaker                   Membership?            @relation(\"MeetingNoteTaker\", fields: [noteTakerMembershipId], references: [id])\n  votes                       Vote[]\n  meetingFinancialGoals       MeetingFinancialGoal[]\n}\n\nmodel MeetingFinancialGoal {\n  id            String                    @id @default(cuid())\n  meetingId     String\n  meeting       Meeting                   @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  name          String\n  targetAmount  Float\n  currentAmount Float                     @default(0)\n  deadline      DateTime?\n  description   String?\n  createdAt     DateTime                  @default(now())\n  updatedAt     DateTime                  @updatedAt\n  contributions MeetingGoalContribution[]\n\n  @@index([meetingId])\n}\n\nmodel MeetingGoalContribution {\n  id           String               @id @default(cuid())\n  goalId       String\n  goal         MeetingFinancialGoal @relation(fields: [goalId], references: [id], onDelete: Cascade)\n  membershipId String\n  membership   Membership           @relation(fields: [membershipId], references: [id], onDelete: Cascade)\n  amount       Float\n  createdAt    DateTime             @default(now())\n\n  @@index([goalId])\n  @@index([membershipId])\n}\n\nmodel MeetingAttendee {\n  id           String           @id @default(cuid())\n  meetingId    String\n  meeting      Meeting          @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  membershipId String\n  membership   Membership       @relation(fields: [membershipId], references: [id], onDelete: Cascade)\n  status       AttendanceStatus @default(PENDING)\n\n  @@unique([meetingId, membershipId])\n}\n\nmodel Vote {\n  id           String       @id @default(cuid())\n  title        String\n  description  String?\n  options      Json\n  startDate    DateTime\n  endDate      DateTime\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n  meetingId    String?\n  meeting      Meeting?     @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  membershipId String\n  membership   Membership   @relation(fields: [membershipId], references: [id], onDelete: Cascade)\n  voteResults  VoteResult[]\n}\n\nmodel VoteResult {\n  id             String     @id @default(cuid())\n  voteId         String\n  vote           Vote       @relation(fields: [voteId], references: [id], onDelete: Cascade)\n  membershipId   String\n  membership     Membership @relation(fields: [membershipId], references: [id], onDelete: Cascade)\n  selectedOption String\n  votedAt        DateTime   @default(now())\n\n  @@unique([voteId, membershipId])\n}\n\n// ==========================================\n// NOTIFICATION MODEL\n// ==========================================\n\nmodel Notification {\n  id                   String           @id @default(cuid())\n  title                String\n  message              String\n  type                 NotificationType\n  isRead               Boolean          @default(false)\n  createdAt            DateTime         @default(now())\n  userId               String\n  user                 User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  relatedGroupId       String?\n  relatedTransactionId String?\n  relatedLoanRequestId String?\n}\n\n// ==========================================\n// LOAN DOCUMENT MODELS\n// ==========================================\n\nmodel PersonalLoanDocuments {\n  id             String   @id @default(cuid())\n  userId         String   @unique\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  Nrcfront       String\n  NrcBack        String\n  PaySlip        String\n  ProofOfAddress String?\n  LiveSelfie     String?\n  BankStatement  String?\n  VideoKycUrl    String? // Level 3: Video KYC recording URL\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\nmodel SolarLoanDocuments {\n  id              String   @id @default(cuid())\n  userId          String   @unique\n  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  Nrcfront        String\n  NrcBack         String\n  LandOwnership   String\n  UtilityBill     String\n  VendorQuotation String\n  SubsidyReceipt  String\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// ==========================================\n// GROUP INVITATION MODEL\n// ==========================================\n\nmodel GroupInvitation {\n  id        String           @id @default(cuid())\n  groupId   String\n  group     Group            @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  inviterId String\n  inviter   User             @relation(\"SentInvitations\", fields: [inviterId], references: [id])\n  inviteeId String\n  invitee   User             @relation(\"ReceivedInvitations\", fields: [inviteeId], references: [id])\n  status    InvitationStatus @default(PENDING)\n  code      String           @unique\n  createdAt DateTime         @default(now())\n  expiresAt DateTime?\n}\n\n// ==========================================\n// WALLET MODEL\n// ==========================================\n\nmodel Wallet {\n  id           String        @id @default(cuid())\n  userId       String        @unique\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  balance      Decimal       @default(0)\n  celoAddress  String?       @unique\n  privateKey   String?\n  celoBalance  String?       @default(\"0\")\n  cusdBalance  String?       @default(\"0\")\n  ceurBalance  String?       @default(\"0\")\n  network      String?       @default(\"alfajores\")\n  isConnected  Boolean       @default(false)\n  connectedAt  DateTime?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  transactions Transaction[]\n}\n\n// ==========================================\n// CONTRIBUTION MODEL\n// ==========================================\n\nmodel Contribution {\n  id            String            @id @default(cuid())\n  amount        Decimal\n  status        TransactionStatus @default(PENDING)\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n  userId        String\n  user          User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  groupId       String\n  group         Group             @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  transactionId String?           @unique\n  transaction   Transaction?      @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n}\n\n// ==========================================\n// LOAN MODELS\n// ==========================================\n\nmodel LoanRequest {\n  id             String        @id @default(cuid())\n  amount         Decimal\n  purpose        String        @db.Text\n  repaymentDate  DateTime\n  repaymentTerms String        @db.Text\n  installments   Int           @default(1)\n  interestRate   Decimal       @default(0)\n  status         LoanStatus    @default(PENDING)\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  userId         String\n  user           User          @relation(\"UserLoanRequests\", fields: [userId], references: [id], onDelete: Cascade)\n  groupId        String\n  group          Group         @relation(\"GroupLoanRequests\", fields: [groupId], references: [id], onDelete: Cascade)\n  transactions   Transaction[]\n  votes          LoanVote[]    @relation(\"LoanRequestVotes\")\n}\n\nmodel LoanVote {\n  id            String      @id @default(cuid())\n  vote          Boolean\n  comment       String?\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n  userId        String\n  user          User        @relation(\"UserLoanVotes\", fields: [userId], references: [id], onDelete: Cascade)\n  loanRequestId String\n  loanRequest   LoanRequest @relation(\"LoanRequestVotes\", fields: [loanRequestId], references: [id], onDelete: Cascade)\n  membershipId  String\n  membership    Membership  @relation(\"MembershipLoanVotes\", fields: [membershipId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, loanRequestId])\n}\n\nmodel IndividualLoan {\n  id               String     @id @default(cuid())\n  userId           String\n  user             User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  serviceType      String\n  serviceName      String\n  serviceCategory  String\n  amount           Decimal\n  purpose          String     @db.Text\n  repaymentPeriod  String\n  fullName         String\n  email            String\n  phone            String\n  nationalId       String\n  address          String     @db.Text\n  employmentStatus String\n  monthlyIncome    Decimal?\n  businessDetails  String?    @db.Text\n  status           LoanStatus @default(PENDING)\n  createdAt        DateTime   @default(now())\n  updatedAt        DateTime   @updatedAt\n\n  @@index([userId])\n  @@index([status])\n}\n\n// ==========================================\n// CONTACT & MEETING REQUEST MODELS\n// ==========================================\n\nmodel ContactMessage {\n  id               String   @id @default(cuid())\n  name             String\n  email            String\n  phone            String?\n  subject          String\n  message          String   @db.Text\n  department       String\n  preferredContact String   @default(\"email\")\n  timeframe        String   @default(\"anytime\")\n  status           String   @default(\"new\")\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([email])\n  @@index([status])\n  @@index([department])\n  @@index([createdAt])\n}\n\nmodel MeetingRequest {\n  id          String   @id @default(cuid())\n  name        String\n  email       String\n  phone       String?\n  meetingDate DateTime\n  meetingTime String\n  purpose     String?  @db.Text\n  status      String   @default(\"pending\")\n  notes       String?  @db.Text\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([email])\n  @@index([status])\n  @@index([meetingDate])\n  @@index([createdAt])\n}\n\n// ==========================================\n// INSURANCE MODELS\n// ==========================================\n\nmodel InsuranceProduct {\n  id                  String   @id @default(cuid())\n  name                String\n  productType         String // crop, health, loan_protection, savings_fraud, mobile, weather\n  description         String   @db.Text\n  coverageAmount      Decimal\n  premiumAmount       Decimal\n  premiumFrequency    String // seasonal, monthly, annual\n  features            String[]\n  requirements        String[]\n  status              String   @default(\"active\") // active, inactive, suspended\n  claimProcessingTime String? // e.g., \"7-14 days\"\n  maxClaimAmount      Decimal?\n  deductible          Decimal? @default(0)\n  coverageTerms       String?  @db.Text // Terms and conditions for coverage\n  exclusions          String?  @db.Text // List of exclusions\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  policies InsurancePolicy[]\n\n  @@index([productType])\n  @@index([status])\n}\n\nmodel InsurancePolicy {\n  id           String           @id @default(cuid())\n  policyNumber String           @unique\n  productId    String\n  product      InsuranceProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n  userId       String\n  user         User             @relation(\"UserInsurancePolicies\", fields: [userId], references: [id], onDelete: Cascade)\n  groupId      String?\n  group        Group?           @relation(\"GroupInsurancePolicies\", fields: [groupId], references: [id], onDelete: Cascade)\n\n  // Coverage Details\n  coverageAmount   Decimal\n  premiumAmount    Decimal\n  premiumFrequency String\n  startDate        DateTime\n  endDate          DateTime\n  renewalDate      DateTime?\n\n  // Status\n  status          String    @default(\"active\") // active, expired, cancelled, claimed\n  paymentStatus   String    @default(\"pending\") // pending, paid, overdue\n  lastPremiumPaid DateTime?\n  nextPremiumDue  DateTime?\n\n  // Additional Details\n  beneficiaries String[]\n  documents     String[]\n  notes         String?  @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  claims   InsuranceClaim[]\n  payments InsurancePremium[]\n\n  @@index([userId])\n  @@index([groupId])\n  @@index([productId])\n  @@index([status])\n  @@index([policyNumber])\n}\n\nmodel InsuranceClaim {\n  id          String          @id @default(cuid())\n  claimNumber String          @unique\n  policyId    String\n  policy      InsurancePolicy @relation(fields: [policyId], references: [id], onDelete: Cascade)\n\n  // Claim Details\n  claimType      String\n  claimAmount    Decimal\n  approvedAmount Decimal?\n  incidentDate   DateTime\n  claimDate      DateTime @default(now())\n  description    String   @db.Text\n\n  // Supporting Documents\n  documents    String[]\n  evidenceUrls String[]\n\n  // Status & Processing\n  status     String    @default(\"submitted\") // submitted, pending, processing, under_review, approved, rejected, paid\n  priority   String    @default(\"normal\") // low, normal, high, urgent\n  assignedTo String?\n  reviewedBy String?\n  reviewedAt DateTime?\n  approvedBy String?\n  approvedAt DateTime?\n  paidAt     DateTime?\n\n  // Rejection/Notes\n  rejectionReason String? @db.Text\n  internalNotes   String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([policyId])\n  @@index([status])\n  @@index([claimNumber])\n}\n\nmodel InsurancePremium {\n  id             String          @id @default(cuid())\n  policyId       String\n  policy         InsurancePolicy @relation(fields: [policyId], references: [id], onDelete: Cascade)\n  amount         Decimal\n  dueDate        DateTime\n  paidDate       DateTime?\n  paymentMethod  String?\n  transactionRef String?\n  status         String          @default(\"pending\") // pending, paid, overdue, waived\n  createdAt      DateTime        @default(now())\n\n  @@index([policyId])\n  @@index([status])\n  @@index([dueDate])\n}\n\n// ==========================================\n// POLLEN LEDGER-DRIVEN FINANCIAL SYSTEM\n// ==========================================\n\n// Ledger Engine - Source of Truth\nmodel LedgerEntry {\n  id      String @id @default(cuid())\n  entryId String @unique // Human-readable entry ID (e.g., \"L001\")\n\n  // Entry Details\n  type     LedgerEntryType\n  amount   Decimal\n  asset    String // cUSD, CELO, ZMW, etc.\n  currency String          @default(\"ZMW\") // ZMW (fiat) or CELO (crypto)\n\n  // User/Entity References\n  userId      String?\n  user        User?   @relation(fields: [userId], references: [id])\n  groupId     String?\n  description String? @db.Text\n  reference   String? // External reference (loan ID, contribution ID, etc.)\n\n  // Blockchain Details (for crypto transactions)\n  txHash        String?\n  blockNumber   Int?\n  walletAddress String?\n  networkId     String? // celo-mainnet, celo-alfajores\n  gasUsed       Decimal?\n  gasFee        Decimal?\n\n  // Status & Verification\n  status        LedgerStatus @default(PENDING)\n  confirmations Int          @default(0)\n  confirmedAt   DateTime?\n\n  // Reconciliation\n  reconciled       Boolean              @default(false)\n  reconciledAt     DateTime?\n  reconciliationId String?\n  reconciliation   DailyReconciliation? @relation(fields: [reconciliationId], references: [id])\n\n  // Reversal tracking\n  reversalOfId String?\n  reversalOf   LedgerEntry?  @relation(\"EntryReversal\", fields: [reversalOfId], references: [id])\n  reversedBy   LedgerEntry[] @relation(\"EntryReversal\")\n\n  // Audit\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([groupId])\n  @@index([type])\n  @@index([status])\n  @@index([currency])\n  @@index([createdAt])\n  @@index([reconciliationId])\n}\n\n// Wallet Execution Layer\nmodel WalletExecution {\n  id String @id @default(cuid())\n\n  // Execution Details\n  executionType ExecutionType\n  direction     ExecutionDirection\n  amount        Decimal\n  asset         String\n  currency      String\n\n  // Source/Destination\n  fromAddress     String?\n  toAddress       String?\n  fromAccountName String?\n  toAccountName   String?\n\n  // Bank/Mobile Money Details\n  bankName       String?\n  accountNumber  String?\n  mobileNumber   String?\n  mobileProvider String? // MTN, Airtel, Zamtel\n\n  // Blockchain Details\n  txHash      String?\n  blockNumber Int?\n  networkId   String?\n  gasLimit    Decimal?\n  gasPrice    Decimal?\n  gasUsed     Decimal?\n  nonce       Int?\n\n  // Status\n  status       ExecutionStatus @default(PENDING)\n  errorMessage String?         @db.Text\n  retryCount   Int             @default(0)\n\n  // Timestamps\n  submittedAt DateTime?\n  confirmedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([executionType])\n  @@index([status])\n  @@index([txHash])\n  @@index([createdAt])\n}\n\n// Village Banking Ledger (Group-level tracking)\nmodel VillageLedger {\n  id      String @id @default(cuid())\n  groupId String @unique\n  group   Group  @relation(fields: [groupId], references: [id], onDelete: Cascade)\n\n  // Running Totals\n  totalContributions  Decimal @default(0)\n  totalLoansIssued    Decimal @default(0)\n  totalRepayments     Decimal @default(0)\n  totalPenalties      Decimal @default(0)\n  totalInterestEarned Decimal @default(0)\n  totalFeesCharged    Decimal @default(0)\n  currentBalance      Decimal @default(0)\n\n  // Member Stats\n  activeMemberCount Int @default(0)\n  totalMemberCount  Int @default(0)\n\n  // Status\n  status         VillageLedgerStatus @default(ACTIVE)\n  lastActivityAt DateTime?\n  createdAt      DateTime            @default(now())\n  updatedAt      DateTime            @updatedAt\n\n  entries VillageLedgerEntry[]\n\n  @@index([groupId])\n  @@index([status])\n}\n\nmodel VillageLedgerEntry {\n  id              String        @id @default(cuid())\n  villageLedgerId String\n  villageLedger   VillageLedger @relation(fields: [villageLedgerId], references: [id], onDelete: Cascade)\n\n  // Entry Details\n  type           VillageLedgerEntryType\n  amount         Decimal\n  runningBalance Decimal // Balance after this entry\n\n  // Member Info\n  memberId   String\n  memberName String\n\n  // Reference\n  reference   String? // Loan ID, contribution ID, etc.\n  description String?\n\n  // Status\n  status LedgerStatus @default(CONFIRMED)\n\n  createdAt DateTime @default(now())\n\n  @@index([villageLedgerId])\n  @@index([memberId])\n  @@index([type])\n  @@index([createdAt])\n}\n\n// Savings Interest Flow\nmodel InterestFlow {\n  id String @id @default(cuid())\n\n  // Period\n  periodStart DateTime\n  periodEnd   DateTime\n  periodType  InterestPeriodType\n\n  // Principal\n  savingsPrincipal Decimal\n\n  // Yield Breakdown\n  grossInterest      Decimal @default(0)\n  platformFee        Decimal @default(0)\n  platformFeeRate    Decimal @default(0.10) // 10% default\n  netInterestToUsers Decimal @default(0)\n\n  // Status\n  status        InterestFlowStatus @default(CALCULATED)\n  distributedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  yieldSources  YieldSource[]\n  distributions InterestDistribution[]\n\n  @@index([periodStart])\n  @@index([periodEnd])\n  @@index([status])\n}\n\nmodel YieldSource {\n  id             String       @id @default(cuid())\n  interestFlowId String\n  interestFlow   InterestFlow @relation(fields: [interestFlowId], references: [id], onDelete: Cascade)\n\n  sourceName      String // AAVE_SUPPLY, LENDING_INTEREST, STAKING_REWARDS, etc.\n  sourceType      YieldSourceType\n  principalAmount Decimal\n  rate            Decimal // APY as decimal (e.g., 0.025 for 2.5%)\n  earnedAmount    Decimal\n\n  // External Reference\n  externalId String? // AAVE position ID, etc.\n\n  createdAt DateTime @default(now())\n\n  @@index([interestFlowId])\n  @@index([sourceType])\n}\n\nmodel InterestDistribution {\n  id             String       @id @default(cuid())\n  interestFlowId String\n  interestFlow   InterestFlow @relation(fields: [interestFlowId], references: [id], onDelete: Cascade)\n\n  // Recipient\n  userId  String\n  user    User    @relation(fields: [userId], references: [id])\n  groupId String?\n\n  // Distribution Details\n  principalShare Decimal // User's share of principal\n  interestAmount Decimal // Interest earned\n  feeDeducted    Decimal // Platform fee deducted\n  netAmount      Decimal // Final amount credited\n\n  // Status\n  status        DistributionStatus @default(PENDING)\n  creditedAt    DateTime?\n  ledgerEntryId String? // Reference to LedgerEntry\n\n  createdAt DateTime @default(now())\n\n  @@index([interestFlowId])\n  @@index([userId])\n  @@index([groupId])\n  @@index([status])\n}\n\n// Daily Reconciliation\nmodel DailyReconciliation {\n  id String @id @default(cuid())\n\n  // Period\n  reconciliationDate DateTime\n\n  // Balances\n  ledgerBalance     Decimal // Total from LedgerEngine\n  bankBalance       Decimal // Total in traditional banking\n  blockchainBalance Decimal // Total on blockchain\n  totalExecuted     Decimal // Bank + Blockchain\n\n  // Difference Analysis\n  difference        Decimal @default(0)\n  differencePercent Decimal @default(0)\n\n  // Status\n  status     ReconciliationStatus @default(PENDING)\n  matchedAt  DateTime?\n  resolvedAt DateTime?\n  resolvedBy String?\n\n  // Notes\n  notes String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  alerts  ReconciliationAlert[]\n  entries LedgerEntry[]\n\n  @@unique([reconciliationDate])\n  @@index([status])\n  @@index([reconciliationDate])\n}\n\nmodel ReconciliationAlert {\n  id               String              @id @default(cuid())\n  reconciliationId String\n  reconciliation   DailyReconciliation @relation(fields: [reconciliationId], references: [id], onDelete: Cascade)\n\n  // Alert Details\n  alertType   AlertType\n  severity    AlertSeverity\n  description String        @db.Text\n  amount      Decimal?\n\n  // Related Entities\n  relatedEntryIds String[]\n  relatedTxHashes String[]\n\n  // Resolution\n  status     AlertStatus @default(OPEN)\n  resolution String?     @db.Text\n  resolvedBy String?\n  resolvedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([reconciliationId])\n  @@index([alertType])\n  @@index([severity])\n  @@index([status])\n}\n\n// Member Balance Tracking\nmodel MemberBalance {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Fiat Balances\n  fiatBalance  Decimal @default(0)\n  fiatCurrency String  @default(\"ZMW\")\n\n  // Crypto Balances\n  celoBalance Decimal @default(0)\n  cusdBalance Decimal @default(0)\n  ceurBalance Decimal @default(0)\n\n  // Locked/Available\n  lockedFiat    Decimal @default(0)\n  lockedCelo    Decimal @default(0)\n  availableFiat Decimal @default(0)\n  availableCelo Decimal @default(0)\n\n  // Interest Tracking\n  totalInterestEarned Decimal @default(0)\n  pendingInterest     Decimal @default(0)\n\n  // Wallet Info\n  primaryWalletAddress String?\n\n  // Last Activity\n  lastTransactionAt    DateTime?\n  lastInterestCreditAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\n// Hub Assets (Available liquidity pools)\nmodel HubAsset {\n  id String @id @default(cuid())\n\n  // Asset Info\n  symbol          String  @unique\n  name            String\n  contractAddress String?\n  decimals        Int     @default(18)\n\n  // Liquidity\n  totalLiquidity     Decimal @default(0)\n  availableLiquidity Decimal @default(0)\n  utilizationRate    Decimal @default(0)\n\n  // Interest Rates\n  supplyAPY          Decimal @default(0)\n  borrowAPY          Decimal @default(0)\n  baseRate           Decimal @default(0)\n  optimalUtilization Decimal @default(0.8)\n\n  // Collateral Settings\n  ltv                  Decimal @default(0)\n  liquidationThreshold Decimal @default(0)\n  liquidationPenalty   Decimal @default(0)\n\n  // Status\n  isActive  Boolean @default(true)\n  canSupply Boolean @default(true)\n  canBorrow Boolean @default(true)\n\n  // Price\n  priceUSD       Decimal   @default(0)\n  priceUpdatedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([symbol])\n  @@index([isActive])\n}\n\n// ==========================================\n// AAVE INTEGRATION MODELS\n// ==========================================\n\nmodel AavePosition {\n  id           String  @id @default(cuid())\n  groupId      String  @unique\n  group        Group   @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  spokeAddress String? // Smart contract address for this group's AAVE spoke\n\n  // Health metrics\n  healthFactor         Decimal @default(0)\n  totalSupplied        Decimal @default(0)\n  totalBorrowed        Decimal @default(0)\n  availableToBorrow    Decimal @default(0)\n  netAPY               Decimal @default(0)\n  liquidationThreshold Decimal @default(0)\n  liquidationRisk      String  @default(\"low\") // low, medium, high\n\n  // Status\n  isActive    Boolean  @default(true)\n  lastUpdated DateTime @default(now())\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  supplies     AaveSupply[]\n  borrows      AaveBorrow[]\n  transactions AaveTransaction[]\n\n  @@index([groupId])\n  @@index([spokeAddress])\n  @@index([isActive])\n}\n\nmodel AaveSupply {\n  id          String       @id @default(cuid())\n  positionId  String\n  position    AavePosition @relation(fields: [positionId], references: [id], onDelete: Cascade)\n  assetSymbol String\n  amount      Decimal\n  apy         Decimal\n  ltv         Decimal\n  balance     Decimal\n  valueUSD    Decimal\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([positionId])\n  @@index([assetSymbol])\n}\n\nmodel AaveBorrow {\n  id          String       @id @default(cuid())\n  positionId  String\n  position    AavePosition @relation(fields: [positionId], references: [id], onDelete: Cascade)\n  assetSymbol String\n  amount      Decimal\n  apy         Decimal\n  balance     Decimal\n  valueUSD    Decimal\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([positionId])\n  @@index([assetSymbol])\n}\n\nmodel AaveTransaction {\n  id          String       @id @default(cuid())\n  positionId  String\n  position    AavePosition @relation(fields: [positionId], references: [id], onDelete: Cascade)\n  type        String // SUPPLY, BORROW, REPAY, WITHDRAW\n  assetSymbol String\n  amount      Decimal\n  txHash      String?\n  status      String       @default(\"pending\") // pending, confirmed, failed\n  timestamp   DateTime     @default(now())\n  createdAt   DateTime     @default(now())\n\n  @@index([positionId])\n  @@index([type])\n  @@index([timestamp])\n}\n\n// ==========================================\n// ENUMS - ORIGINAL\n// ==========================================\n\nenum GroupPrivacy {\n  PUBLIC\n  PRIVATE\n  INVITE_ONLY\n}\n\nenum GovernanceType {\n  ADMIN\n  MULTI_ADMIN\n  ONE_VOTE_PER_PERSON\n  ONE_VOTE_DEPOSIT\n}\n\nenum ContributionFrequency {\n  WEEKLY\n  BI_WEEKLY\n  MONTHLY\n}\n\nenum MeetingFrequency {\n  WEEKLY\n  BI_WEEKLY\n  MONTHLY\n}\n\nenum MembershipRole {\n  OWNER\n  ADMIN\n  MEMBER\n}\n\nenum MembershipStatus {\n  PENDING\n  ACTIVE\n  SUSPENDED\n  DECLINED\n  ACCEPTED\n  APPROVED\n  INACTIVE\n}\n\nenum TransactionType {\n  DEPOSIT\n  WITHDRAWAL\n  CONTRIBUTION\n  INTEREST\n  FEE\n  PENALTY\n  LOAN_DISBURSEMENT\n  LOAN_REPAYMENT\n}\n\nenum TransactionStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\nenum AttendanceStatus {\n  PENDING\n  PRESENT\n  ABSENT\n  EXCUSED\n}\n\nenum NotificationType {\n  PAYMENT_DUE\n  PAYMENT_RECEIVED\n  NEW_MEMBER\n  MEETING_REMINDER\n  WITHDRAWAL_REQUEST\n  LOAN_REQUEST\n  LOAN_APPROVED\n  LOAN_REJECTED\n  LOAN_REPAYMENT_DUE\n  SYSTEM\n}\n\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n  EXPIRED\n}\n\nenum GroupStatus {\n  ACTIVE\n  INACTIVE\n  COMPLETED\n  ARCHIVED\n}\n\nenum LoanStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  DISBURSED\n  REPAYING\n  REPAID\n  DEFAULTED\n}\n\n// ==========================================\n// ENUMS - POLLEN LEDGER SYSTEM\n// ==========================================\n\nenum LedgerEntryType {\n  DEPOSIT\n  WITHDRAW\n  TRANSFER\n  INTEREST\n  FEE\n  ADJUSTMENT\n  LOAN_DISBURSEMENT\n  LOAN_REPAYMENT\n  CONTRIBUTION\n  PENALTY\n}\n\nenum LedgerStatus {\n  PENDING\n  CONFIRMED\n  FAILED\n  REVERSED\n}\n\nenum ExecutionType {\n  BANK_TRANSFER\n  MOBILE_MONEY\n  BLOCKCHAIN\n}\n\nenum ExecutionDirection {\n  INBOUND\n  OUTBOUND\n}\n\nenum ExecutionStatus {\n  PENDING\n  SUBMITTED\n  CONFIRMED\n  FAILED\n}\n\nenum VillageLedgerStatus {\n  ACTIVE\n  SUSPENDED\n  CLOSED\n}\n\nenum VillageLedgerEntryType {\n  CONTRIBUTION\n  LOAN_DISBURSEMENT\n  LOAN_REPAYMENT\n  PENALTY\n  INTEREST\n  FEE\n  ADJUSTMENT\n}\n\nenum InterestPeriodType {\n  DAILY\n  WEEKLY\n  MONTHLY\n}\n\nenum InterestFlowStatus {\n  CALCULATED\n  DISTRIBUTED\n  FAILED\n}\n\nenum YieldSourceType {\n  DEFI\n  TRADITIONAL\n  STAKING\n}\n\nenum DistributionStatus {\n  PENDING\n  CREDITED\n  FAILED\n}\n\nenum ReconciliationStatus {\n  PENDING\n  MATCHED\n  ALERT\n  RESOLVED\n}\n\nenum AlertType {\n  MISMATCH\n  PENDING_TRANSACTION\n  DUPLICATE\n  UNAUTHORIZED\n}\n\nenum AlertSeverity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum AlertStatus {\n  OPEN\n  INVESTIGATING\n  RESOLVED\n  FALSE_POSITIVE\n}\n"
}

